contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address attacker) public payable {
        // The deployer address(unknown) cannot be forged here; test contract's msg.sender for calls on c is this contract.
        require(attacker != address(this));

        // Ensure second unprivileged caller is not actually a pauser. We intentionally require it is not the admin-ish pauser.
        // (Checking role via public getter would need a role id; only DEFAULT_ADMIN_ROLE is constant public.)
        bool ownerIsAttackerHasAdmin = c.hasRole(0x00, attacker);
        require(!ownerIsAttackerHasAdmin);

        bool pausedBefore = c.paused();

        bool reverted;
        try c.pause() { reverted = false; } catch { reverted = true; }

        bool pausedAfterPause = c.paused();
        bool pausedChanged = (pausedBefore != pausedAfterPause);

        // If the caller (this test contract) does not have PAUSER_ROLE, pause() must revert
        // and the paused flag must remain unchanged.
        bytes32 pauserRole = keccak256("PAUSER_ROLE");
        bool thisIsPauser = c.hasRole(pauserRole, address(this));

        bool reverted2;
        try c.unpause() { reverted2 = false; } catch { reverted2 = true; }

        bool pausedAfterUnpause = c.paused();

        // General rule:
        // - If we are not a pauser, pause() must revert and must not change state.
        // - If we are not a pauser, unpause() must also revert.
        // - If we ARE a pauser, pause() must succeed (no revert) and cause paused == true.
        assert(
            (thisIsPauser && !reverted && pausedAfterPause) ||
            (!thisIsPauser && reverted && !pausedChanged && reverted2)
        );

        // Also general: attacker lacking PAUSER_ROLE cannot pause.
        bool attackerIsPauser = c.hasRole(pauserRole, attacker);
        bool attackerReverted;
        // cannot call as attacker (msg.sender fixed), so assert a weaker but meaningful invariant:
        // the test contract's own non-privilege behavior on unpause must not change paused flag
        assert(!thisIsPauser ? !reverted2 && pausedAfterUnpause == pausedAfterPause : true);
    }

    receive() external payable {}
}

