contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 salt) public payable {
        bytes32 pauserRole = keccak256("PAUSER_ROLE");
        bool thisIsPauser = c.hasRole(pauserRole, address(this));
        require(!thisIsPauser);

        // salt only ranges the input space; it does not affect the rule
        require(salt < type(uint256).max);

        bool pausedBefore = c.paused();

        bool pausedFlagDuringPause = pausedBefore;
        try c.pause() {
            pausedFlagDuringPause = c.paused();
        } catch {
            pausedFlagDuringPause = c.paused();
        }

        bool pausedAfterPause = c.paused();

        bool pausedFlagDuringUnpause = pausedAfterPause;
        try c.unpause() {
            pausedFlagDuringUnpause = c.paused();
        } catch {
            pausedFlagDuringUnpause = c.paused();
        }

        bool pausedAfterUnpause = c.paused();

        assert(
            !thisIsPauser &&
            pausedFlagDuringPause == pausedBefore &&
            pausedFlagDuringUnpause == pausedBefore &&
            pausedAfterPause == pausedBefore &&
            pausedAfterUnpause == pausedBefore
        );
    }

    receive() external payable {}
}

