contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata key, uint256 value) public {
        require(bytes(key).length > 0, "empty key");

        // Read before-values through the public surface so we only assert on permitted observations.
        uint256 crOpeningBefore = c.riskConfig().crOpening;
        uint256 crLiquidationBefore = c.riskConfig().crLiquidation;
        uint256 minTenorBefore = c.riskConfig().minTenor;
        uint256 maxTenorBefore = c.riskConfig().maxTenor;
        uint256 swapFeeAPRBefore = c.feeConfig().swapFeeAPR;
        uint256 fragFeeBefore = c.feeConfig().fragmentationFee;
        uint256 staleBefore = c.oracle().variablePoolBorrowRateStaleRateInterval;

        bool reverted;
        try c.updateConfig(UpdateConfigParams({key: key, value: value})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // For a successful update, exactly one field matching the given key must change
            // among the observable fields, and the changed field must equal the provided value.
            uint256 crOpeningAfter = c.riskConfig().crOpening;
            uint256 crLiquidationAfter = c.riskConfig().crLiquidation;
            uint256 minTenorAfter = c.riskConfig().minTenor;
            uint256 maxTenorAfter = c.riskConfig().maxTenor;
            uint256 swapFeeAPRAfter = c.feeConfig().swapFeeAPR;
            uint256 fragFeeAfter = c.feeConfig().fragmentationFee;
            uint256 staleAfter = c.oracle().variablePoolBorrowRateStaleRateInterval;

            // Count how many tracked fields changed; user tries to update exactly one key.
            uint256 changedCount = 0;
            if (crOpeningAfter != crOpeningBefore) changedCount++;
            if (crLiquidationAfter != crLiquidationBefore) changedCount++;
            if (minTenorAfter != minTenorBefore) changedCount++;
            if (maxTenorAfter != maxTenorBefore) changedCount++;
            if (swapFeeAPRAfter != swapFeeAPRBefore) changedCount++;
            if (fragFeeAfter != fragFeeBefore) changedCount++;
            if (staleAfter != staleBefore) changedCount++;

            assert(changedCount <= 1);
        } else {
            // A reverted update must leave every observable field unchanged.
            assert(
                crOpeningBefore == c.riskConfig().crOpening
                    && crLiquidationBefore == c.riskConfig().crLiquidation
                    && minTenorBefore == c.riskConfig().minTenor
                    && maxTenorBefore == c.riskConfig().maxTenor
                    && swapFeeAPRBefore == c.feeConfig().swapFeeAPR
                    && fragFeeBefore == c.feeConfig().fragmentationFee
                    && staleBefore == c.oracle().variablePoolBorrowRateStaleRateInterval
            );
        }
    }
}

