contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address someUser, uint256 withdrawAmount) public payable {
        // Create an isolated user whose only interaction with c is via this test contract.
        address u = address(uint160(uint256(keccak256(abi.encodePacked(someUser, withdrawAmount)))) | 0x1000000000000000000000000000000000000000);

        c.deposit{value: msg.value}(DepositParams({token: address(c.data().underlyingBorrowToken), amount: msg.value, to: address(this)}));

        require(withdrawAmount > 0, "amount must be positive");

        IERC20Metadata collTok = c.data().underlyingCollateralToken;
        address rec = address(uint160(uint256(keccak256(abi.encodePacked(u, withdrawAmount)))) | 0x2000000000000000000000000000000000000000);

        uint256 balBefore = collTok.balanceOf(address(c));
        uint256 recBefore = collTok.balanceOf(rec);

        bool reverted;
        try c.withdraw{value: 0}(WithdrawParams({token: address(collTok), amount: withdrawAmount, to: rec})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = collTok.balanceOf(address(c));
        uint256 recAfter = collTok.balanceOf(rec);

        if (reverted) {
            // withdrawal must revert because the caller has no collateral to withdraw
            assert(balAfter == balBefore && recAfter == recBefore);
        } else {
            // successful withdrawal moves exactly the capped amount of underlying collateral tokens to the recipient
            uint256 amount = withdrawAmount < 0 ? 0 : withdrawAmount;
            assert(recAfter >= recBefore);
            assert(balBefore == balAfter || balBefore > balAfter);
            assert(recAfter - recBefore <= amount);
            assert(balAfter + (recAfter - recBefore) == balBefore);
        }
    }

    receive() external payable {}
}

